/**
 * Enforces Mithor-Platforms HARD RULE #1:
 * "No AI attribution anywhere. No 'Claude', no 'Generated by', no Co-authored-by —
 * in commits, PR titles/bodies, code comments, or docs."
 */

const ATTRIBUTION_LINE_REGEXES = [
  /^\s*Co-authored-by:.*$/gim,
  /^\s*Generated (?:by|with)\b.*$/gim,
  /^\s*🤖\s*Generated.*$/gim
];

const INLINE_FORBIDDEN_REPLACEMENTS = [
  { pattern: /\b(?:Generated by|Created by)\s+(?:Claude|DeepSeek|Antigravity|AI)\b/gi, replacement: "" },
  { pattern: /🤖/g, replacement: "" }
];

export function hasForbiddenAiAttribution(text, customForbidden = []) {
  if (!text) return { hasViolation: false, matches: [] };
  const matches = [];
  const checks = [
    /Co-authored-by:/i,
    /Generated (?:by|with)\s+(?:Claude|DeepSeek|Antigravity|AI)/i,
    /\bClaude\s+Code\b/i,
    /\bDeepSeek\s+Harness\b/i,
    /🤖/
  ];
  for (const rx of checks) {
    if (rx.test(text)) {
      matches.push(rx.source);
    }
  }
  for (const word of customForbidden) {
    if (word && text.toLowerCase().includes(String(word).toLowerCase())) {
      matches.push(word);
    }
  }
  return {
    hasViolation: matches.length > 0,
    matches: [...new Set(matches)]
  };
}

/**
 * Strips any AI attribution lines and markers from commit messages or PR descriptions.
 */
export function sanitizeGitText(text) {
  if (!text) return "";
  let cleaned = String(text);
  for (const rx of ATTRIBUTION_LINE_REGEXES) {
    cleaned = cleaned.replace(rx, "");
  }
  for (const { pattern, replacement } of INLINE_FORBIDDEN_REPLACEMENTS) {
    cleaned = cleaned.replace(pattern, replacement);
  }
  cleaned = cleaned
    .replace(/\bClaude\b/gi, "")
    .replace(/\bDeepSeek\b/gi, "")
    .replace(/\bAntigravity\b/gi, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  return cleaned;
}
